<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/header.php'; $rows=$pdo->query("SELECT p.*,b.bill_no,u.full_name FROM payments p JOIN bills b ON b.id=p.bill_id JOIN users u ON u.id=p.cashier_id ORDER BY p.id DESC")->fetchAll();?><h2>Malipo / Receipts</h2><div class="actions"><a class="btn" href="../prints/receipts.php" target="_blank">Print Receipts Zote</a></div><table><tr><th>Receipt</th><th>Bill</th><th>Kiasi</th><th>Method</th><th>Reference</th><th>Cashier</th><th>Tarehe</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['receipt_no'])?></td><td><?=e($r['bill_no'])?></td><td>TSh <?=number_format($r['amount'],2)?></td><td><?=e($r['method'])?></td><td><?=e($r['reference_no'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['paid_at'])?></td><td><a class="btn gray" target="_blank" href="../prints/receipt.php?id=<?=$r['id']?>">Receipt</a></td></tr><?php endforeach;?></table><?php require_once __DIR__.'/../config/footer.php'; ?>
